package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class PoseStoreTest {
 static JSONObject testCase(String id) throws Exception {for(Object raw:PoseDevelopmentTest.suite().getJSONArray("cases")){var c=(JSONObject)raw;if(c.getString("id").equals(id))return c;}throw new IllegalArgumentException(id);}
 static JSONObject start(PoseStore store,String name,boolean realtime,boolean orientation) throws Exception {var c=testCase(name);var scene=PoseDevelopmentTest.scene(c);var plan=PosePlan.build(scene,PosePlan.intent(scene,c.getJSONArray("targets"),c.getDouble("forceLimitN"),c.getDouble("torqueLimitNm")));return store.start(UUID.randomUUID().toString(),UUID.randomUUID().toString(),scene,plan,realtime,orientation);}
 static JSONObject waitFor(PoseStore s,String id,String status) throws Exception {for(int n=0;n<12000;n++){var r=s.run(id);if(r.getString("status").equals(status))return r;if(!r.getString("status").equals("running"))fail(r.optString("reason"));Thread.sleep(5);}throw new AssertionError("Native pose task did not settle");}
 @Test public void actualStoredRotationAndAllBodyWrenchEvidenceAreIndependentlyChecked() throws Exception {try(var s=new PoseStore(Files.createTempDirectory("pose034-store-"))){var r=start(s,"dev034-opposite-turn",false,true);r=waitFor(s,r.getString("id"),"completed");var m=PoseVerify.verify(r);assertTrue(m.toString(),m.getBoolean("passed"));assertEquals(2,m.getInt("grabs"));assertEquals(2,m.getInt("releases"));assertTrue(m.getDouble("maxTorqueNm")>0);assertTrue(m.getInt("contactPoints")>0);assertTrue(m.getDouble("maxBystanderDriftM")<=.05);final JSONObject original=r;var bad=new JSONObject(r.toString());bad.getJSONArray("samples").getJSONObject(0).getJSONArray("integration").getJSONArray(0).put(1,"foreign-body");assertThrows(IllegalStateException.class,()->PoseVerify.verify(bad));var wrong=new JSONObject(r.toString());wrong.getJSONArray("samples").getJSONObject(0).put("torqueEffortNms",100);assertThrows(IllegalStateException.class,()->PoseVerify.verify(wrong));var lost=new JSONObject(r.toString());lost.getJSONArray("samples").getJSONObject(1).getJSONArray("bodies").remove(2);assertThrows(IllegalStateException.class,()->PoseVerify.verify(lost));}}
 @Test public void allBodiesAndHeldOrientationResumeWithoutRepeatingCommittedEffects() throws Exception {Path root=Files.createTempDirectory("pose034-resume-");String id;JSONObject saved;try(var s=new PoseStore(root)){var r=start(s,"dev034-three-objects",true,true);id=r.getString("id");boolean rotating=false;for(int i=0;i<3000;i++){var sample=s.snapshot().optJSONObject("sample");if(sample!=null&&sample.getInt("tick")>=960&&sample.getJSONObject("controller").getString("phase").equals("move")&&sample.getJSONObject("controller").getInt("stage")==1&&PoseVerify.norm(sample.getJSONArray("bodies").getJSONObject(0).getJSONArray("angularVelocity"))>.2){rotating=true;break;}Thread.sleep(5);}assertTrue("Actual moving orientation observed",rotating);s.pause();saved=waitFor(s,id,"paused");assertTrue(saved.getJSONArray("samples").length()>1);}try(var s=new PoseStore(root)){s.resume(id,saved.getJSONObject("definition"),false);var r=waitFor(s,id,"completed");var m=PoseVerify.verify(r);assertTrue(m.toString(),m.getBoolean("passed"));assertEquals(1,m.getInt("resumes"));assertEquals(0,m.getDouble("maxRestorePositionErrorM"),2e-6);assertEquals(0,m.getDouble("maxRestoreVelocityError"),2e-6);for(int i=0;i<saved.getJSONArray("samples").length();i++)assertTrue(saved.getJSONArray("samples").getJSONObject(i).similar(r.getJSONArray("samples").getJSONObject(i)));}}
 @Test public void corruptedCheckpointCannotReplaceTheNativeWorld() throws Exception {Path root=Files.createTempDirectory("pose034-corrupt-");String id;JSONObject scene;try(var s=new PoseStore(root)){var r=start(s,"dev034-quarter-turn",true,true);id=r.getString("id");scene=r.getJSONObject("definition");Thread.sleep(300);s.pause();waitFor(s,id,"paused");}Path file=root.resolve("pose-tasks/checkpoints/"+id+".json");var data=new JSONObject(Files.readString(file));data.getJSONObject("payload").getJSONObject("physics").getJSONArray("bodies").getJSONObject(0).getJSONArray("angularVelocity").put(1,9);String edited=data.toString();Files.writeString(file,edited);try(var s=new PoseStore(root)){assertThrows(IllegalStateException.class,()->s.resume(id,scene,false));assertNotEquals("running",s.status(id));}assertEquals(edited,Files.readString(file));}
 @Test public void seenTranslationAblationRetainsTheFourMatchedCasesAndPhysicalNegatives() throws Exception {Path root=Files.createTempDirectory("pose034-ablation-development-");double a=0,b=0;int matched=0;for(Object raw:PoseDevelopmentTest.suite().getJSONArray("cases")){var c=(JSONObject)raw;if(!c.getString("split").equals("development"))continue;var baseline=PoseDevelopmentTest.run(c,false);var candidate=PoseDevelopmentTest.run(c,true);Files.writeString(root.resolve(c.getString("id")+"-baseline.json"),baseline.toString());Files.writeString(root.resolve(c.getString("id")+"-candidate.json"),candidate.toString());boolean bp=baseline.getJSONObject("verification").getBoolean("passed"),np=candidate.getJSONObject("verification").getBoolean("passed");if(bp&&np){matched++;a+=baseline.getJSONObject("verification").getDouble("effortNs");b+=candidate.getJSONObject("verification").getDouble("effortNs");}if(c.getBoolean("negativeControl"))assertFalse(bp);if(bp)assertTrue(np);}assertEquals(4,matched);System.out.println("POSE_TRANSLATION_DEVELOPMENT_034 matched="+matched+" effortRatio="+(b/a)+" folder="+root);assertTrue(b/a<=1.1);}
}
